mapper.select:
SELECT other, reason, evidence, first_seen_at FROM (
  SELECT user_b AS other, reason, evidence, first_seen_at FROM riskalert_link WHERE user_a = #{userId}
  UNION ALL
  SELECT user_a AS other, reason, evidence, first_seen_at FROM riskalert_link WHERE user_b = #{userId}
) t ORDER BY other, reason

SELECT user_b FROM riskalert_link WHERE user_a = #{userId}
UNION
SELECT user_a FROM riskalert_link WHERE user_b = #{userId}
ORDER BY 1

SELECT COUNT(*) FROM riskalert_alert
WHERE user_id = #{userId} AND status IN ('NEW', 'SEEN') AND created_at >= #{since}
  AND kind IN #{k}
